package com.anthony6996.hardcorecompass.manager;
import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.storage.PlayerData;import java.util.UUID;
public final class LivesManager{private final ConfigManager config;private final PlayerData storage;public LivesManager(ConfigManager c,PlayerData s){config=c;storage=s;}public int lives(UUID id){return storage.getLives(id,config.startingLives());}public int deaths(UUID id){return storage.getDeaths(id);}public boolean hasPreservedCompass(UUID id){return storage.hasPreservedCompass(id);}public boolean isInitialized(UUID id){return storage.exists(id);}public void initialize(UUID id){if(!storage.exists(id)){storage.setLives(id,config.startingLives());storage.save();}}public int recordDeath(UUID id){initialize(id);storage.incrementDeaths(id);int n=Math.max(0,lives(id)-1);storage.setLives(id,n);storage.save();return n;}public boolean markCompassPreserved(UUID id){if(storage.hasPreservedCompass(id))return false;storage.setHasPreservedCompass(id,true);storage.save();return true;}public void set(UUID id,int n){storage.setLives(id,Math.max(0,n));storage.save();}public void reset(UUID id){storage.reset(id);storage.setLives(id,config.startingLives());storage.save();}public void resetDeaths(UUID id){storage.resetDeaths(id);storage.save();}public void save(){storage.save();}}
